#include <stdio.h>
#define MAXN 15

int main(void)
{
    int n, i, j, t;
    int a[MAXN], b[MAXN];

    scanf("%d", &n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    for (i = 0; i < n; i++)
        scanf("%d", &b[i]);

    /* 按 i 从小到大依次交换 a[i] 与 a[b[i]]，每次交换都基于当前数组 */
    for (i = 0; i < n; i++)
    {
        j = b[i];
        t = a[i];
        a[i] = a[j];
        a[j] = t;
    }

    for (i = 0; i < n; i++)
        printf("%d%c", a[i], i == n - 1 ? '\n' : ' ');

    return 0;
}

#include <stdio.h>
