int main(void)
{
    int n, m, i, q, key, pos;
    int a[MAXN];

    scanf("%d", &n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);

    scanf("%d", &m);
    for (q = 0; q < m; q++)
    {
        scanf("%d", &key);
