            printf("%d\n", a[1]);
        else if (pos == n - 1)
            printf("%d\n", a[n - 2]);
        else
            printf("%d %d\n", a[pos - 1], a[pos + 1]);
    }

    return 0;
}

#include <stdio.h>
#define MAXN 1005

int main(void)
{
    int n, i, j, min, t;
    int a[MAXN];

    scanf("%d", &n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);

    /* 选择排序：从小到大 */
    for (i = 0; i < n - 1; i++)
    {
        min = i;
        for (j = i + 1; j < n; j++)
            if (a[j] < a[min])
                min = j;
        if (min != i)
        {
            t = a[i];
            a[i] = a[min];
            a[min] = t;
        }
    }

    printf("%d %d %d %d\n", a[n - 1], a[n - 2], a[0], a[1]);
    return 0;
}

