/* 起泡排序：从小到大 */
void bubbleSort(int a[], int n)
{
    int i, j, t, swapped;
    for (i = 0; i < n - 1; i++)
    {
        swapped = 0;
        for (j = 0; j < n - 1 - i; j++)
            if (a[j] > a[j + 1])
            {
                t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
                swapped = 1;
            }
        if (!swapped)
            break;
    }
}

/* 依次输出数组元素，数之间一个空格，最后一个数后换行 */
void outputData(int data[], int elementCount)
{
    int i;
    for (i = 0; i < elementCount; i++)
        printf("%d%c", data[i], i == elementCount - 1 ? '\n' : ' ');
}

#include <stdio.h>
#define MAXN 105

void shift(int *array, int num, int size);

int main(void)
{
    int i, n, p;
    int array[MAXN];

    scanf("%d%d", &n, &p);
    for (i = 0; i < n; i++)
        scanf("%d", &array[i]);

    shift(array, p, n); /* 向左移 p 位 */

    for (i = 0; i < n; i++)
        printf("%d%c", array[i], i == n - 1 ? '\n' : ' ');

    return 0;
}

/* 将数组循环左移 num 位 */
void shift(int *array, int num, int size)
{
    int i, k, t;

    num %= size;
    for (k = 0; k < num; k++)
    {
        t = array[0];
        for (i = 1; i < size; i++)
            array[i - 1] = array[i];
        array[size - 1] = t;
    }
}

#include <stdio.h>
#define MAXN 1005

int main(void)
{
    int a[MAXN], b[MAXN];
    int na = 0, nb = 0;
    int x, i, j, same, ok;

    /* 读到 -1 为止，-1 不属于序列 */
    while (scanf("%d", &x) == 1 && x != -1)
        a[na++] = x;
    while (scanf("%d", &x) == 1 && x != -1)
        b[nb++] = x;

    ok = 0;
    if (nb <= na)
    {
        for (i = 0; i + nb <= na && !ok; i++)
        {
            same = 1;
            for (j = 0; j < nb; j++)
                if (a[i + j] != b[j])
                {
                    same = 0;
                    break;
                }
            if (same)
                ok = 1;
        }
    }

    if (ok)
        printf("ListB is the sub sequence of ListA.\n");
    else
        printf("ListB is not the sub sequence of ListA.\n");

    return 0;
}

#include <stdio.h>
#define MAXV 101

int main(void)
{
    int n, i, v, best = 0, first = 1;
    int freq[MAXV] = {0};

    scanf("%d", &n);
    for (i = 0; i < n; i++)
    {
        scanf("%d", &v);
        freq[v]++;
    }

    /* 先找出最大出现次数 */
    for (v = 0; v < MAXV; v++)
        if (freq[v] > best)
            best = freq[v];

    /* 再从小到大输出所有众数 */
    for (v = 0; v < MAXV; v++)
        if (freq[v] == best)
        {
            printf(first ? "%d" : " %d", v);
            first = 0;
        }
    printf("\n");

    return 0;
}

#include <stdio.h>
#define MAXN 1005

int main(void)
{
    int n, i, j, k = 0, dup;
    int a[MAXN], b[MAXN];

    scanf("%d", &n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);

    /* 依次处理，若该值已在结果数组中出现过就跳过 */
    for (i = 0; i < n; i++)
    {
        dup = 0;
        for (j = 0; j < k; j++)
            if (b[j] == a[i])
            {
                dup = 1;
                break;
            }
        if (!dup)
            b[k++] = a[i];
    }

    printf("%d\n", k);
    for (i = 0; i < k; i++)
        printf("%d%c", b[i], i == k - 1 ? '\n' : ' ');

    return 0;
}

