#include <stdio.h>
#define MAXN 2000005

int num[MAXN];

int BinarySearch(int a[], int n, int key);

int main(void)
{
    int n, m, i, key;

    scanf("%d%d", &n, &m);
    for (i = 0; i < n; i++)
        scanf("%d", &num[i]);

    for (i = 0; i < m; i++)
    {
        scanf("%d", &key);
        printf("%d", BinarySearch(num, n, key));
        if (i != m - 1)
            printf(" ");
        else
            printf("\n");
    }

    return 0;
}

/* 二分查找：找到返回下标（从 0 开始），否则返回 -1 */
int BinarySearch(int a[], int n, int key)
{
    int left = 0, right = n - 1, mid;

    while (left <= right)
    {
        mid = left + (right - left) / 2;
        if (a[mid] == key)
            return mid;
        else if (a[mid] < key)
            left = mid + 1;
        else
            right = mid - 1;
    }
    return -1;
}

#include <stdio.h>
#define MAXN 100005

int a[MAXN], b[MAXN], c[2 * MAXN];

int main(void)
{
    int n, m, i, j, k;

    scanf("%d", &n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    scanf("%d", &m);
    for (i = 0; i < m; i++)
        scanf("%d", &b[i]);

    /* 双指针归并 */
    i = 0;
    j = 0;
    k = 0;
    while (i < n && j < m)
    {
        if (a[i] <= b[j])
            c[k++] = a[i++];
        else
            c[k++] = b[j++];
    }
    while (i < n)
        c[k++] = a[i++];
    while (j < m)
        c[k++] = b[j++];

    for (i = 0; i < k; i++)
        printf("%d%c", c[i], i == k - 1 ? '\n' : ' ');

    return 0;
}
